(7442036, 1176695, 181814, '<td valign="top">I really like the pastel colors and the composition is very well done.</td>', 'I really like the pastel colors and the composition is very well done.', '2016-03-08 19:26:33.000000', NULL, 1),
(7442037, 1176632, 181814, '<td valign="top">It is suggestive for sure, I like the composition and the creativity.</td>', 'It is suggestive for sure, I like the composition and the creativity.', '2016-03-08 19:27:25.000000', NULL, 1),
(7442042, 1176951, 181814, '<td valign="top">This is really well done I like the bright colors and the focus is great.</td>', 'This is really well done I like the bright colors and the focus is great.', '2016-03-08 19:33:01.000000', NULL, 1),
(7442047, 1176537, 181814, '<td valign="top">I like this it is very well done and creative. Are those some sort of ribbons?</td>', 'I like this it is very well done and creative. Are those some sort of ribbons?', '2016-03-08 19:35:30.000000', NULL, 1),
(7442054, 1176946, 181814, '<td valign="top">I really like this a lot, it is one of my favorites for sure. I like all the different shades of orange, the exposure and focus and composition are all excellently done.</td>', 'I really like this a lot, it is one of my favorites for sure. I like all the different shades of orange, the exposure and focus and composition are all excellently done.', '2016-03-08 19:38:36.000000', NULL, 1),
(7442058, 1176928, 181814, '<td valign="top">Nice lighting very well composed and looks really good.</td>', 'Nice lighting very well composed and looks really good.', '2016-03-08 19:39:39.000000', NULL, 1),
(7442061, 1176907, 181814, '<td valign="top">Very nice photograph with excellent lighting and good focus. This is definitely one of my top picks for sure.</td>', 'Very nice photograph with excellent lighting and good focus. This is definitely one of my top picks for sure.', '2016-03-08 19:41:42.000000', NULL, 1),
(7442089, 1176637, 35545, '<td valign="top">Nice colors and rhythm.</td>', 'Nice colors and rhythm.', '2016-03-08 21:24:58.000000', NULL, 1),
(7442090, 1176945, 97225, '<td valign="top">Beautiful harmony of colour in a great abstract design. My top pick.</td>', 'Beautiful harmony of colour in a great abstract design. My top pick.', '2016-03-08 21:26:36.000000', NULL, 1),
(7442092, 1176465, 97225, '<td valign="top">Beautiful, glowing colours and flowing shape. On of my ribbon choices.</td>', 'Beautiful, glowing colours and flowing shape. On of my ribbon choices.', '2016-03-08 21:27:51.000000', NULL, 1),
(7442094, 1176951, 35545, '<td valign="top">Nice colors and movement.</td>', 'Nice colors and movement.', '2016-03-08 21:29:46.000000', NULL, 1),
(7442096, 1176921, 35545, '<td valign="top">I really like the picture, but to me, it''s too representational to be considered abstract.</td>', 'I really like the picture, but to me, it''s too representational to be considered abstract.', '2016-03-08 21:40:24.000000', NULL, 1),
(7442097, 1176845, 35545, '<td valign="top">I like the forms and shadows, but I''d like to see touches of other colors.</td>', 'I like the forms and shadows, but I''d like to see touches of other colors.', '2016-03-08 21:41:45.000000', NULL, 1),
(7442099, 1176549, 50695, '<td valign="top">this evokes abstraction, even though it is representational, because of simple geometric shapes and mostly solid planes of color.</td>', 'this evokes abstraction, even though it is representational, because of simple geometric shapes and mostly solid planes of color.', '2016-03-08 21:42:24.000000', NULL, 1),
(7442100, 1176954, 50695, '<td valign="top">you create abstraction with complexity and movement, and bright color... as though you are shaking us out of reality.</td>', 'you create abstraction with complexity and movement, and bright color... as though you are shaking us out of reality.', '2016-03-08 21:43:22.000000', NULL, 1),
(7442101, 1176657, 50695, '<td valign="top">this becomes abstract with large, swooping shapes and hatching lines. the art filter takes it a step too far for my taste. I prefer seeing how abstraction flows naturally from the real.</td>', 'this becomes abstract with large, swooping shapes and hatching lines. the art filter takes it a step too far for my taste. I prefer seeing how abstraction flows naturally from the real.', '2016-03-08 21:45:49.000000', NULL, 1),
(7442102, 1176692, 50695, '<td valign="top">I dislike the title, but the image itself is excellent. it''s my favorite sort of abstraction, alternating between completely representational and completely abstract, and the composition is very strong, stable but dynamic.</td>', 'I dislike the title, but the image itself is excellent. it''s my favorite sort of abstraction, alternating between completely representational and completely abstract, and the composition is very strong, stable but dynamic.', '2016-03-08 21:48:06.000000', NULL, 1),
(7442104, 1176929, 50695, '<td valign="top">this is abstract because you took a picture of geometric shapes. it''s more a picture of abstract stuff than an abstract picture.</td>', 'this is abstract because you took a picture of geometric shapes. it''s more a picture of abstract stuff than an abstract picture.', '2016-03-08 21:49:09.000000', NULL, 1),
(7442106, 1176944, 50695, '<td valign="top">reality is torn apart to make it abstract, as though we are looking at a layer of reality beneath a layer of abstraction. in this way, it''s like a metaphor for human vision, the way we layer concepts onto everything we see. I like the smile to counterbalance the violence of the broken image.</td>', 'reality is torn apart to make it abstract, as though we are looking at a layer of reality beneath a layer of abstraction. in this way, it''s like a metaphor for human vision, the way we layer concepts onto everything we see. I like the smile to counterbalance the violence of the broken image.', '2016-03-08 21:51:07.000000', NULL, 1),
(7442107, 1176598, 50695, '<td valign="top">this reminds us that abstraction does not have to be spontaneous or mysterious. extremely mundane things, like the NBC peacock, are abstract.</td>', 'this reminds us that abstraction does not have to be spontaneous or mysterious. extremely mundane things, like the NBC peacock, are abstract.', '2016-03-08 21:52:10.000000', NULL, 1),
(7442108, 1176855, 50695, '<td valign="top">great balls of abstraction! we don''t know what they are. we wonder if we are seeing their action instead of the thing itself. abstraction is a form of not knowing.</td>', 'great balls of abstraction! we don''t know what they are. we wonder if we are seeing their action instead of the thing itself. abstraction is a form of not knowing.', '2016-03-08 21:53:25.000000', NULL, 1),
(7442109, 1176747, 50695, '<td valign="top">one jolt of motion blur can add a layer of unreality to a scene, make it seem painted, threaten it with nonexistence, because pure abstraction is oblivion.</td>', 'one jolt of motion blur can add a layer of unreality to a scene, make it seem painted, threaten it with nonexistence, because pure abstraction is oblivion.', '2016-03-08 21:54:38.000000', NULL, 1),
(7442110, 1176417, 50695, '<td valign="top">nature is not pure math, or it''s math so complex we can''t predict it, but we can clearly see that math works in nature. you show us the math and abstraction of nature just by leaning in close enough.</td>', 'nature is not pure math, or it''s math so complex we can''t predict it, but we can clearly see that math works in nature. you show us the math and abstraction of nature just by leaning in close enough.', '2016-03-08 21:56:06.000000', NULL, 1),
(7442111, 1176428, 50695, '<td valign="top">flatware, or whatever this is, is already abstract. you are just taking a picture of its abstraction, and to be doubly safe, you seem to have added an art filter. I like the colors, but I don''t like safety (in photography).</td>', 'flatware, or whatever this is, is already abstract. you are just taking a picture of its abstraction, and to be doubly safe, you seem to have added an art filter. I like the colors, but I don''t like safety (in photography).', '2016-03-08 21:57:31.000000', NULL, 1),
(7442112, 1176464, 50695, '<td valign="top">abstraction can strip away the clutter of reality. a yard is nature abstracted. life is reduced to a uniform two-inch layer. wildness is only seen as discolorations in the lawn.</td>', 'abstraction can strip away the clutter of reality. a yard is nature abstracted. life is reduced to a uniform two-inch layer. wildness is only seen as discolorations in the lawn.', '2016-03-08 21:59:26.000000', NULL, 1),
(7442113, 1176923, 50695, '<td valign="top">changing colors of reality can jolt us out of normal ways of seeing, so that at first we only see shapes... in other words, we see the abstraction of the scene. This technique would be more interesting if it were of a subject that wasn''t already abstract.</td>', 'changing colors of reality can jolt us out of normal ways of seeing, so that at first we only see shapes... in other words, we see the abstraction of the scene. This technique would be more interesting if it were of a subject that wasn''t already abstract.', '2016-03-08 22:00:41.000000', NULL, 1),
(7442114, 1176827, 50695, '<td valign="top">a picture of an abstract drawing(?) seen through water droplets. certainly abstract, but water droplets are so common here that it''s hard to make them interesting. mostly, they are a one trick pony.</td>', 'a picture of an abstract drawing(?) seen through water droplets. certainly abstract, but water droplets are so common here that it''s hard to make them interesting. mostly, they are a one trick pony.', '2016-03-08 22:02:30.000000', NULL, 1),
(7442115, 1176900, 50695, '<td valign="top">a picture of a toy that is already abstract, so the abstraction of the picture is not very interesting. But I do like the tight crop, the circle fighting the square.</td>', 'a picture of a toy that is already abstract, so the abstraction of the picture is not very interesting. But I do like the tight crop, the circle fighting the square.', '2016-03-08 22:03:32.000000', NULL, 1),
(7442117, 1176955, 50695, '<td valign="top">you have gone deep into the realm of abstraction, so far that I have no sense of the "reality" you started with. But the texture is so rich that it almost evokes new realities. good colors, too.</td>', 'you have gone deep into the realm of abstraction, so far that I have no sense of the "reality" you started with. But the texture is so rich that it almost evokes new realities. good colors, too.', '2016-03-08 22:04:48.000000', NULL, 1),
(7442118, 1176714, 50695, '<td valign="top">architecture is abstract, certainly. it is manmade space, and implies that we are inherently abstracters of nature.</td>', 'architecture is abstract, certainly. it is manmade space, and implies that we are inherently abstracters of nature.', '2016-03-08 22:05:56.000000', NULL, 1),
(7442123, 1176940, 50695, '<td valign="top">blur brings abstraction by removing detail. something is lost but something is gained. and sometimes the loss is what we really want, to shield ourselves from the exhausting excruciating details of life. a bulldozer can become a melody of yellow.</td>', 'blur brings abstraction by removing detail. something is lost but something is gained. and sometimes the loss is what we really want, to shield ourselves from the exhausting excruciating details of life. a bulldozer can become a melody of yellow.', '2016-03-08 22:09:34.000000', NULL, 1),
(7442125, 1176958, 50695, '<td valign="top">over long spans of time, wind sculpts out its abstract visions, with the grace of aching slowness</td>', 'over long spans of time, wind sculpts out its abstract visions, with the grace of aching slowness', '2016-03-08 22:10:37.000000', NULL, 1),
(7442127, 1176705, 50695, '<td valign="top">the circle, and its child, the cylinder, are the most perfect of abstractions. so perfect they can become boring... always a danger with abstraction, which generally does not have a story to bolster it.</td>', 'the circle, and its child, the cylinder, are the most perfect of abstractions. so perfect they can become boring... always a danger with abstraction, which generally does not have a story to bolster it.', '2016-03-08 22:12:11.000000', NULL, 1),
(7442129, 1176603, 50695, '<td valign="top">abstraction can turn the visual to aural. patterns and textures become rhythms, colors and shapes become melodies. it looks like you might have simplified or at least intensified the color of the scene. that and the framing nudge us to see the scape more abstractly.</td>', 'abstraction can turn the visual to aural. patterns and textures become rhythms, colors and shapes become melodies. it looks like you might have simplified or at least intensified the color of the scene. that and the framing nudge us to see the scape more abstractly.', '2016-03-08 22:13:44.000000', NULL, 1),
(7442130, 1176912, 50695, '<td valign="top">extreme motion blur wipes out all reality, forcing us to watch the dance of light.</td>', 'extreme motion blur wipes out all reality, forcing us to watch the dance of light.', '2016-03-08 22:14:42.000000', NULL, 1),
(7442131, 1176722, 50695, '<td valign="top">close-up framing, emphasizing symmetry, forces us to see abstractly. what keeps my interest is the asymmetry of color and backgrounds. a smart combination of symmetry and asymmetry can create a very interesting image while still being completely abstract.</td>', 'close-up framing, emphasizing symmetry, forces us to see abstractly. what keeps my interest is the asymmetry of color and backgrounds. a smart combination of symmetry and asymmetry can create a very interesting image while still being completely abstract.', '2016-03-08 22:16:28.000000', NULL, 1),
(7442132, 1176905, 50695, '<td valign="top">nature imitates a fractal, revealing smaller and smaller patterns that remind you of the big patterns. These patterns are the inherent abstractness of nature.</td>', 'nature imitates a fractal, revealing smaller and smaller patterns that remind you of the big patterns. These patterns are the inherent abstractness of nature.', '2016-03-08 22:17:28.000000', NULL, 1),
(7442135, 1176945, 50695, '<td valign="top">inside abstracts the outside. this is nowhere better symbolized than window curtains, forcing their moire onto the gentle swaying of trees and sunlight.</td>', 'inside abstracts the outside. this is nowhere better symbolized than window curtains, forcing their moire onto the gentle swaying of trees and sunlight.', '2016-03-08 22:22:01.000000', NULL, 1),
(7442136, 1176927, 50695, '<td valign="top">close-up and inversion can cause us to lose our sense of scale and perspective... which in turn forces us into imagined landscapes. Abstraction can therefore be a mode of transportation.</td>', 'close-up and inversion can cause us to lose our sense of scale and perspective... which in turn forces us into imagined landscapes. Abstraction can therefore be a mode of transportation.', '2016-03-08 22:23:49.000000', NULL, 1),
(7442137, 1176835, 50695, '<td valign="top">is this a pet''s ear? by going in close and glancing along the edges of a thing, you can make it nothing at all, and this nothing is abstraction, and can have its own beauty.</td>', 'is this a pet''s ear? by going in close and glancing along the edges of a thing, you can make it nothing at all, and this nothing is abstraction, and can have its own beauty.', '2016-03-08 22:24:46.000000', NULL, 1),
(7442138, 1176936, 50695, '<td valign="top">an extremely obvious abstract pattern distorted by a transparency of some sort, stuck right in the center of the image. this sort of stability makes an image forgettable... though I do like the colors of the art you are taking a picture of.</td>', 'an extremely obvious abstract pattern distorted by a transparency of some sort, stuck right in the center of the image. this sort of stability makes an image forgettable... though I do like the colors of the art you are taking a picture of.', '2016-03-08 22:26:29.000000', NULL, 1),
(7442139, 1176907, 50695, '<td valign="top">another cylinder. yes, a cylinder is abstract, so technically, taking a picture of it is abstract... but it is also terribly representational. I do like your use of shadows though.</td>', 'another cylinder. yes, a cylinder is abstract, so technically, taking a picture of it is abstract... but it is also terribly representational. I do like your use of shadows though.', '2016-03-08 22:27:44.000000', NULL, 1),
(7442141, 1176419, 50695, '<td valign="top">ah we''ve had the coniferous and now the deciduous. yes, by sticking your face into nature, you make it abstract. getting too close offends the eyes and they protect themselves with abstraction, removing the reality of what confronts us.</td>', 'ah we''ve had the coniferous and now the deciduous. yes, by sticking your face into nature, you make it abstract. getting too close offends the eyes and they protect themselves with abstraction, removing the reality of what confronts us.', '2016-03-08 22:29:12.000000', NULL, 1),
(7442142, 1176928, 50695, '<td valign="top">material realigns itself as it is subjected to various pressures and positions. this realignment is very abstract in nature. it''s physics, and physics is math, and math is abstract.</td>', 'material realigns itself as it is subjected to various pressures and positions. this realignment is very abstract in nature. it''s physics, and physics is math, and math is abstract.', '2016-03-08 22:31:05.000000', NULL, 1),
(7442143, 1176818, 50695, '<td valign="top">this strikes me as some sort of optical effect, which is of course abstract, since it completely destroys the "reality" behind it. a lovely swirl of color and lines. I like spirals and cousins of spirals... they suggest a cycle but also change.</td>', 'this strikes me as some sort of optical effect, which is of course abstract, since it completely destroys the "reality" behind it. a lovely swirl of color and lines. I like spirals and cousins of spirals... they suggest a cycle but also change.', '2016-03-08 22:32:36.000000', NULL, 1),
(7442145, 1176845, 50695, '<td valign="top">you have succeeded in making this utterly unrecognizable to me. But the simple shapes connected in complicated ways suggest a profound story...<br/> <br/>oh dear, I suddenly realized this is probably just a photo of artwork...</td>', 'you have succeeded in making this utterly unrecognizable to me. But the simple shapes connected in complicated ways suggest a profound story... oh dear, I suddenly realized this is probably just a photo of artwork...', '2016-03-08 22:34:33.000000', NULL, 1),
(7442146, 1176695, 50695, '<td valign="top">obviously this is completely abstract, just colors and circles. I find the colors lovely and I like how the shapes of color interact with the arrangement of circles.</td>', 'obviously this is completely abstract, just colors and circles. I find the colors lovely and I like how the shapes of color interact with the arrangement of circles.', '2016-03-08 22:35:29.000000', NULL, 1),
(7442147, 1176906, 50695, '<td valign="top">the layers of reality, things on the surface, things poking up from the surface, and things reflected on the surface, combine ... in a sense, too much reality becomes abstract.</td>', 'the layers of reality, things on the surface, things poking up from the surface, and things reflected on the surface, combine ... in a sense, too much reality becomes abstract.', '2016-03-08 22:36:32.000000', NULL, 1),
(7442149, 1176938, 50695, '<td valign="top">abstractions can be seeds of new ideas (but there''s nothing new about this photo, though I do like the composition. it has more of a sense of perspective and therefore scale than this shot usually does)</td>', 'abstractions can be seeds of new ideas (but there''s nothing new about this photo, though I do like the composition. it has more of a sense of perspective and therefore scale than this shot usually does)', '2016-03-08 22:54:20.000000', NULL, 1),
(7442150, 1176470, 50695, '<td valign="top">the water is angry. it''s turning the birds into monsters. its magic is abstraction.</td>', 'the water is angry. it''s turning the birds into monsters. its magic is abstraction.', '2016-03-08 22:55:11.000000', NULL, 1),
(7442151, 1176951, 50695, '<td valign="top">things can get so complex that we can only resolve them into rhythms. this is a way to be abstract.</td>', 'things can get so complex that we can only resolve them into rhythms. this is a way to be abstract.', '2016-03-08 22:55:51.000000', NULL, 1),
(7442152, 1176808, 50695, '<td valign="top">handkerchief<br/> <br/>a little malleable plane of abstraction right in our own pockets.</td>', 'handkerchief a little malleable plane of abstraction right in our own pockets.', '2016-03-08 22:56:45.000000', NULL, 1),
(7442153, 1176915, 50695, '<td valign="top">a harsh motion blur turns the world into evil roses. <br/> <br/>see how the mind fights against abstraction, turns it into other representations. abstraction can be exhilarating because it stimulates the mind in this way.</td>', 'a harsh motion blur turns the world into evil roses.  see how the mind fights against abstraction, turns it into other representations. abstraction can be exhilarating because it stimulates the mind in this way.', '2016-03-08 22:58:21.000000', NULL, 1),
(7442154, 1176549, 163081, '<td valign="top">different approach of abstract, I would call it more minimalism. The frames are not aligned, maybe move some steps to the right would have helped. A 7 from me</td>', 'different approach of abstract, I would call it more minimalism. The frames are not aligned, maybe move some steps to the right would have helped. A 7 from me', '2016-03-08 22:59:01.000000', NULL, 1),
(7442155, 1176659, 50695, '<td valign="top">abstraction can be comforting when it''s simple, like a gold star from a teacher. I suggest as a title, "Candy"</td>', 'abstraction can be comforting when it''s simple, like a gold star from a teacher. I suggest as a title, "Candy"', '2016-03-08 23:00:14.000000', NULL, 1),
(7442156, 1176944, 163081, '<td valign="top">It''s funny because I have the same door window at home and my kids are posing behind it. great portrait, good abstract. 7 from me</td>', 'It''s funny because I have the same door window at home and my kids are posing behind it. great portrait, good abstract. 7 from me', '2016-03-08 23:00:45.000000', NULL, 1),
(7442157, 1176604, 50695, '<td valign="top">when we organize into groups, we are in danger of losing our individuality. collectivization is a kind of abstraction.</td>', 'when we organize into groups, we are in danger of losing our individuality. collectivization is a kind of abstraction.', '2016-03-08 23:01:07.000000', NULL, 1),
(7442158, 1176465, 50695, '<td valign="top">paper is abstract. emptiness is a kind of abstraction. dullness is a kind of abstraction.</td>', 'paper is abstract. emptiness is a kind of abstraction. dullness is a kind of abstraction.', '2016-03-08 23:01:49.000000', NULL, 1),
(7442159, 1176534, 50695, '<td valign="top">cataracts force the water to reveal its forces, which are essentially abstract.</td>', 'cataracts force the water to reveal its forces, which are essentially abstract.', '2016-03-08 23:02:29.000000', NULL, 1),
(7442160, 1176637, 50695, '<td valign="top">paper is abstract. crinkling is abstract. colors are abstract. if things are simple enough, or empty enough, or both, they are abstract because our mind can''t do anything with them.</td>', 'paper is abstract. crinkling is abstract. colors are abstract. if things are simple enough, or empty enough, or both, they are abstract because our mind can''t do anything with them.', '2016-03-08 23:03:45.000000', NULL, 1),
(7442161, 1176845, 114285, '<td valign="top">I''d love to know what this is, it''s so mysterious. My top pick, all the best!</td>', 'I''d love to know what this is, it''s so mysterious. My top pick, all the best!', '2016-03-08 23:04:16.000000', NULL, 1),
(7442162, 1176917, 50695, '<td valign="top">extreme glare and motion obliterates representation, so all we see are glare and motion and they look the same. this is the deep chemistry of abstraction.</td>', 'extreme glare and motion obliterates representation, so all we see are glare and motion and they look the same. this is the deep chemistry of abstraction.', '2016-03-08 23:04:43.000000', NULL, 1),
(7442163, 1176914, 50695, '<td valign="top">abstraction can make an object more sinister because we''re not quite sure what it is. oh dear, is it sharp? how close is it?</td>', 'abstraction can make an object more sinister because we''re not quite sure what it is. oh dear, is it sharp? how close is it?', '2016-03-08 23:05:47.000000', NULL, 1),
(7442165, 1176822, 50695, '<td valign="top">pure abstraction. just rhythms of light over rhythms of color. enough variety to keep it interesting, and therefore pleasing to the eye.</td>', 'pure abstraction. just rhythms of light over rhythms of color. enough variety to keep it interesting, and therefore pleasing to the eye.', '2016-03-08 23:08:21.000000', NULL, 1),
(7442166, 1176537, 50695, '<td valign="top">the swaths have abstract patterns but are also themselves used as part of an abstract pattern. randomness can be abstract but so can orderliness. anything that removes the subject and leaves only the motion of seeing.</td>', 'the swaths have abstract patterns but are also themselves used as part of an abstract pattern. randomness can be abstract but so can orderliness. anything that removes the subject and leaves only the motion of seeing.', '2016-03-08 23:10:14.000000', NULL, 1),
(7442167, 1176919, 50695, '<td valign="top">blur obliterates the thing and leaves only the abstract... the highlights, the colors, and the shadows... this is like a floating city</td>', 'blur obliterates the thing and leaves only the abstract... the highlights, the colors, and the shadows... this is like a floating city', '2016-03-08 23:11:21.000000', NULL, 1),
(7442168, 1176655, 50695, '<td valign="top">this suggests an orderly but destructive motion. we see the beauty of dissipation in all its abstract glory... almost an eye looking back at us.</td>', 'this suggests an orderly but destructive motion. we see the beauty of dissipation in all its abstract glory... almost an eye looking back at us.', '2016-03-08 23:12:45.000000', NULL, 1),
(7442169, 1176904, 50695, '<td valign="top">yes language is abstract. a foreign language reminds us how abstract it is. any connection to reality is manufactured in our minds.</td>', 'yes language is abstract. a foreign language reminds us how abstract it is. any connection to reality is manufactured in our minds.', '2016-03-08 23:13:40.000000', NULL, 1),
