INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7442409, 1176470, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that meets the challenge well<br/> <br/>You''re right Alice, some of the very best abstracts come from water reflections and you have found an excellent one here, well done there is certainly plenty of colour and the bird is well abstracted. I must confess to be a sucker for reflections, I love the reed shapes and the birds head they are beautifully distorted. Perhaps the only thing I would alter is the composition to have more space in front rather than behind but perhaps this was unavoidable for you at the time?<br/> <br/>It''s disappointing for you that it wasn''t better received but thanks for your entry Alice.<br/></td>', 'Hello from the critique club An appealing image that meets the challenge well You''re right Alice, some of the very best abstracts come from water reflections and you have found an excellent one here, well done there is certainly plenty of colour and the bird is well abstracted. I must confess to be a sucker for reflections, I love the reed shapes and the birds head they are beautifully distorted. Perhaps the only thing I would alter is the composition to have more space in front rather than behind but perhaps this was unavoidable for you at the time? It''s disappointing for you that it wasn''t better received but thanks for your entry Alice.', '2016-03-09 13:21:14.000000', NULL, 0),
(7442411, 1176922, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that meets the challenge well<br/> <br/>A great idea Clara, the resulting colours and shapes have produced an original and colourful abstract and therefore fulfilled the challenge brief well. The bright vivid colours work well against the darker water background, I like the shape to the upper right with the blue nose it reminds me of Venetian carnival mask looking down.<br/> <br/>The only constructive remark I would like to make is that there is some softness top and bottom due to the way the camera was probably held, ie., at an angle to the surface, by holding the camera accurately horizontal to the surface this would have been avoided. I wouldn''t say that the softness detracts in any detrimental way so this just meant to be constructive help.<br/> <br/>Its great to see your involvement at such a young age and the creativity you have shown here promises very well for the future, I look forward to seeing more from you, thanks for your entry Clara</td>', 'Hello from the critique club An appealing image that meets the challenge well A great idea Clara, the resulting colours and shapes have produced an original and colourful abstract and therefore fulfilled the challenge brief well. The bright vivid colours work well against the darker water background, I like the shape to the upper right with the blue nose it reminds me of Venetian carnival mask looking down. The only constructive remark I would like to make is that there is some softness top and bottom due to the way the camera was probably held, ie., at an angle to the surface, by holding the camera accurately horizontal to the surface this would have been avoided. I wouldn''t say that the softness detracts in any detrimental way so this just meant to be constructive help. Its great to see your involvement at such a young age and the creativity you have shown here promises very well for the future, I look forward to seeing more from you, thanks for your entry Clara', '2016-03-09 13:36:59.000000', NULL, 0),
(7442412, 1176465, 80096, '<td valign="top">Congrats on your blue ribbon!!</td>', 'Congrats on your blue ribbon!!', '2016-03-09 13:42:57.000000', NULL, 0),
(7442413, 1176818, 80096, '<td valign="top">Congrats!! One of my favorites!</td>', 'Congrats!! One of my favorites!', '2016-03-09 13:44:14.000000', NULL, 0),
(7442423, 1176692, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that meets the challenge well<br/> <br/>Thank you for your description, as a result I obviously have a huge benefit over the voters! This is seriously abstract, whilst I do like abstracts I usually like to retain some element of reference from which to reconstruct the original, here there is no way and as such I find it more difficult to appreciate and comment constructively. I think I would probably have opted for a crop within what I see here probably a square of the bottom portion of the image where I find the shapes and shades and fuzziness a little more appealing.<br/> <br/>Thanks for an intriguing and stimulating entry Ronnie.</td>', 'Hello from the critique club An appealing image that meets the challenge well Thank you for your description, as a result I obviously have a huge benefit over the voters! This is seriously abstract, whilst I do like abstracts I usually like to retain some element of reference from which to reconstruct the original, here there is no way and as such I find it more difficult to appreciate and comment constructively. I think I would probably have opted for a crop within what I see here probably a square of the bottom portion of the image where I find the shapes and shades and fuzziness a little more appealing. Thanks for an intriguing and stimulating entry Ronnie.', '2016-03-09 14:01:44.000000', NULL, 0),
(7442467, 1176818, 97225, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by JakeKurdsjuk:</b></div><hr/><i> If this was done in some way other than the flip n fold &amp; twirl that would require expert editing I''d love to know how you did it. </i></td></tr></table> <br/> <br/>Me too.</td>', 'Originally posted by JakeKurdsjuk: If this was done in some way other than the flip n fold & twirl that would require expert editing I''d love to know how you did it.   Me too.', '2016-03-09 16:10:09.000000', NULL, 0),
(7442469, 1176845, 97225, '<td valign="top">Congratulations on the HM. This is very creative - so creative that I mistook it for a close up of part of an oil painting. No doubt that effect is due to a texture added in pp. The end result is cool.</td>', 'Congratulations on the HM. This is very creative - so creative that I mistook it for a close up of part of an oil painting. No doubt that effect is due to a texture added in pp. The end result is cool.', '2016-03-09 16:15:23.000000', NULL, 0),
